// =============================================================================
/**
 * [공시 제출] 공통 함수를 작성한다.
 * 
 * @description 1. 기존 as-is에서 header.jsp에 선언되어있는 공통 함수
 *              2. fn_으로 시작하는 함수명을 to-be명명규칙에 맞게 카멜케이스로 변경
 *              3. 공시제출 업무에 사용되는 공통팝업 호출 함수
 * @author 최서희
 * @class dis
 * @namespace $c.dis
 */
// =============================================================================
scwin.onpageload = function () {

};

/**
 * @method
 * @name initGridSettings
 * @description 공시제출 그리드뷰 사용시 공통적으로 적용되는 설정값 세팅. 
 *              존재하는 컴포넌트만 표준 적용 됨.
 *              적용하고싶지 않은 공통은 컴포넌트를 id를 매핑하지 않으면 자동생략 됨.
 * @hidden N
 * @exception 
 * @example $c.dis.initGridSettings();
 * 
 * [필요 컴포넌트] - 없는 경우 자동생략
 *  __initPageSize : sel_size
 *  __initDateValidation : ipt_startDate, ipt_endDate
 *  __initEnterSearch : grp_search, (fn)scwin.btn_search_onclick
 */
scwin.initGridSettings = function () {
    const page = $p;
    const modules = [
        "__initPageSize",
        "__initDateValidation",
        "__initEnterSearch"
    ];

    const fnSearch = $c.util.getFunction("scwin.btn_search_onclick");

    modules.forEach(function (fnName) {
        try {
            scwin[fnName](page, fnSearch);
        } catch (e) {
            console.error(fnName, e);
        }
    });
};

/**
 * @method
 * @name __initPageSize
 * @description 페이지 사이즈 selectbox생성
 * @param {string} page 화면 컴포넌트
 * @hidden Y
 * @exception 
 * @example ${example}
 */
scwin.__initPageSize = function (page) {
    const sel_size = page.getComponentById("sel_size");
    if (!sel_size) {
        return;
    }
    $c.data.comboCbDataSetDynamic(sel_size, [15, 30, 50, 100], 0);
};

/**
 * @method
 * @name __initDateValidation
 * @description 기간 유효성 검증
 * @param {string} page 화면 컴포넌트
 * @hidden Y
 * @exception 
 * @example ${example}
 */
scwin.__initDateValidation = function (page) {
    const ipt_startDate = page.getComponentById("ipt_startDate");
    const ipt_endDate = page.getComponentById("ipt_endDate");
    if (!ipt_startDate || !ipt_endDate) {
        return;
    }
    $c.date.compareFromToDate(ipt_startDate, ipt_endDate, ["시작일", "종료일"], "yyyyMMdd");
};

/**
 * @method
 * @name __initEnterSearch
 * @description 엔터키 조회
 * @param {string} page 화면 컴포넌트
 * @param {function} fnSearch 조회함수
 * @hidden Y
 * @exception 
 * @example ${example}
 */
scwin.__initEnterSearch = function (page, fnSearch) {
    const grp_search = page.getComponentById("grp_search");
    if (!grp_search || typeof fnSearch != "function") {
        return;
    }
    $c.win.setEnterKeyEvent(grp_search, fnSearch);
};



/**
 * @method
 * @name getFromDateByPeriod
 * @description 오늘 날짜 기준으로 type에 해당하는 기간의 시작날짜 구하는 함수
 * @param {string} type 1week(1주), 1month(1개월), 3개월, 6개월, 1year(1년), 2년, 3년, all(전체)
 * @hidden N
 * @exception 
 * @example $c.dis.getFromDateByPeriod("1week");
 */
scwin.getFromDateByPeriod = function (type) {
    let edate = $c.date.getServerDateTime("yyyyMMdd"); //today
    let sdate = "";
    switch (type) {
        case "1week":
            sdate = $c.date.addDate(edate, -7);
            break;
        case "1month":
            sdate = $c.date.addMonth(edate, -1);
            break;
        case "3month":
            sdate = $c.date.addMonth(edate, -3);
            break;
        case "6month":
            sdate = $c.date.addMonth(edate, -6);
            break;
        case "1year":
            sdate = $c.date.addYear(edate, -1);
            break;
        case "2year":
            sdate = $c.date.addYear(edate, -2);
            break;
        case "3year":
            sdate = $c.date.addYear(edate, -3);
            break;
        case "all":
            sdate = "";
            break;
        default:
            break;
    }
    return sdate;
};




