/**
 * @method
 * @name callFormInfoLayer
 * @description 보고서 선택 팝업
 * @param {string} param
 * @hidden N
 * @exception 
 * @example 
    let disclsFormList = [
        {
            formKorNm: row.formKorNm,
            fromVer: row.beforeFormVer,
            data: {
                idx: idx,
                isOld: "Y",
                rowFn: "goWrite"
            }
        }
    ];
    const param = {
        callbackFn: "scwin.formInfoLayerCallback",
        isFormVer: "Y",
        dataList: disclsFormList
    };

    $c.dis.callFormInfoLayer(param);
 */
scwin.callFormInfoLayer = function (param) {
    let height = 81;
    if (param.dataList && param.dataList.length > 1) {
        for (let i = 1; i < param.dataList.length; i++) {
            height += 38;
        }
    }

    const options = {
        id: "FormInfoLayer",
        type: "pageFramePopup",
        popupName: "아래중 작성하실 보고서를 선택하세요",
        width: "500",
        height: height,
        resizable: false
    };
    $c.win.openPopup("/ui/dis/common/formInfo_layer.xml", options, param);
};


